const typos={stresed:'stressed',stres:'stress',exauhsted:'exhausted',exhuasted:'exhausted',tierd:'tired',studing:'studying',travle:'travel',freind:'friend',freinds:'friends',relatioship:'relationship',lonley:'lonely',boredd:'bored',musci:'music'};
const vocabulary=['stressed','stress','tired','exhausted','study','studying','music','books','movies','lonely','travel','coffee','friends','friend','weekend','relationship','sleep','sleepy','bored','jokes','thanks'];
function editDistance(a,b){if(Math.abs(a.length-b.length)>1)return 2;let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const next=[i];for(let j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,row[j]+1,row[j-1]+(a[i-1]===b[j-1]?0:1));row=next}return row[b.length]}
function repairWord(w){if(vocabulary.includes(w))return w;const collapsed=w.replace(/([a-z])\1{2,}/g,'$1$1');const elongated=vocabulary.filter(v=>v.replace(/([a-z])\1+/g,'$1')===w.replace(/([a-z])\1+/g,'$1'));if(/([a-z])\1{2,}/.test(w)&&elongated.length===1)return elongated[0];if(w.length<5||w.length>24)return collapsed;const near=vocabulary.filter(v=>editDistance(w,v)===1);return near.length===1?near[0]:collapsed}
function normalize(value){return String(value).normalize('NFKC').toLowerCase().replace(/[‘’]/g,"'").replace(/\b[a-z]+\b/g,w=>{if(/^h+e+y+$/.test(w))return'hey';if(/^h+i+$/.test(w))return'hi';if(/^h+e+l+o+$/.test(w))return'hello';if(/^y+o+$/.test(w))return'yo';if(/^o+k+a*y*$/.test(w))return'okay';if(/^y+e+s+$|^y+e+a+h+$|^y+u+p+$|^y+e+p+$/.test(w))return'yes';if(/^n+a+h+$|^n+o+p+e+$|^n+o+$/.test(w))return'no';if(/^h+m+$/.test(w))return'hmm';if(/^t+h+a+n+k+s+$/.test(w))return'thanks';return typos[w]||repairWord(w)}).replace(/\b(wyd|hru|wbu|hbu|idk|dunno|tbh|ngl|rn|kinda|sorta|wanna|gonna|pls|plz|thx|ty|tmr|tmrw|u|ur|r|im|ive|dont|cant|isnt|didnt)\b/g,w=>({wyd:'what are you doing',hru:'how are you',wbu:'what about you',hbu:'how about you',idk:'i do not know',dunno:'i do not know',tbh:'',ngl:'',rn:'right now',kinda:'kind of',sorta:'sort of',wanna:'want to',gonna:'going to',pls:'please',plz:'please',thx:'thanks',ty:'thanks',tmr:'tomorrow',tmrw:'tomorrow',u:'you',ur:'your',r:'are',im:"i'm",ive:"i've",dont:"don't",cant:"can't",isnt:"isn't",didnt:"didn't"})[w]).replace(/([哈嗯哦呀啊])\1+/g,'$1$1').replace(/\s+/g,' ').trim()}
